<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api} from '../api'

type Row=Record<string,any>
const courses=ref<Row[]>([]),terms=ref<Row[]>([]),data=ref<Row|null>(null),courseId=ref(''),loading=ref(false),tab=ref('overview')
const filters=reactive({term_id:'',campus:'',cohort_year:'',major:'',class_id:'',class_variant:'',teaching_level:'',record_type:'',status:''})
const importOpen=ref(false),importStep=ref(0),working=ref(false),chosen=ref<File[]>([]),batch=ref<Row|null>(null)
const uploadProgress=reactive({current:0,total:0,uploaded:0,skipped:0,failed:0,currentName:''})
const uploadFailures=ref<Row[]>([])
const duplicateOpen=ref(false)
const failureOpen=ref(false)
const defaults=reactive({term_id:'',campus:'',cohort_year:'',major:'',class_variant:'',teaching_level:''})
const detailOpen=ref(false),item=ref<Row|null>(null),previewOpen=ref(false),previewDoc=ref<Row|null>(null),previewHtml=ref(''),previewUrl=ref(''),previewError=ref(''),pptHost=ref<HTMLElement|null>(null)
const classOpen=ref(false),classForm=reactive({term_id:'',class_name:'',campus:'',cohort_year:'',major:'',class_variant:'',teaching_level:'',teaching_time_slot:''})
const compareLeft=ref(''),compareRight=ref(''),comparison=ref<Row|null>(null)
const labels:Row={syllabus_profile:'课程大纲',lesson_session:'教案课次',teaching_schedule_entry:'教学进度',assessment_scheme:'考核方案',assessment_component:'考核组成',experiment_project:'实验项目',experiment_material:'实验材料',experiment_report:'实验报告',teaching_reflection:'教学反思',other:'其他档案'}
const docLabels:Row={syllabus:'教学大纲',lesson_plan:'教案',teaching_schedule:'教学进度',assessment:'考核标准',experiment_material:'实验材料',experiment_report:'实验报告',slides:'课件',knowledge_graph:'知识图谱',question_bank:'题库',other:'其他'}
const routeLabels:Row={teaching_archive:'教学档案',knowledge_center:'知识中心',question_center:'习题中心',attachment:'实验附件',ignored:'忽略'}
const riskLabels:Row={assessment_weight_mismatch:'考核比例不等于100%',legacy_conversion_unavailable:'旧版 Office 转换服务不可用',missing_source:'缺少来源定位',no_structured_content:'未识别到结构化内容',lesson_sequence_gap:'教案课次不连续',experiment_sequence_gap:'实验编号不连续或重复',executable_content_blocked:'可执行文件已拦截',manual_route_required:'需在目标中心确认入库',archive_contains_executable:'压缩包包含可执行文件',nested_archive_requires_review:'包含嵌套压缩包',processing_failed:'处理失败'}
const items=computed(()=>data.value?.items||[]),versions=computed(()=>data.value?.versions||[]),classes=computed(()=>data.value?.classes||[]),documents=computed(()=>data.value?.documents||[]),attachments=computed(()=>data.value?.attachments||[])
const metrics=computed(()=>data.value?.metrics||{completeness:0,published_documents:0,review_required:0,class_coverage:0,hours_consistent:true})
const byType=(type:string)=>items.value.filter((x:Row)=>x.record_type===type)
const reviewItems=computed(()=>items.value.filter((x:Row)=>x.lifecycle==='review_required'))
const duplicateRows=computed(()=>(batch.value?.files||[]).filter((x:Row)=>x.duplicate_action==='skip'||x.risk_codes?.includes('duplicate_existing_document')||x.risk_codes?.includes('duplicate_in_batch')))
const options=(key:string)=>[...new Set([...versions.value,...classes.value].map((x:Row)=>x[key]).filter(Boolean))]
const params=()=>Object.fromEntries(Object.entries(filters).filter(([,v])=>v))
const tree=computed(()=>{const roots=new Map<string,Row>();for(const v of versions.value){const key=`${v.academic_year||'未设置学年'} · ${v.teaching_period||v.term_name||'未设置学期'}`;if(!roots.has(key))roots.set(key,{label:key,children:[]});const root=roots.get(key)!;const campus=v.campus||'课程通用';let branch=root.children.find((x:Row)=>x.label===campus);if(!branch){branch={label:campus,children:[]};root.children.push(branch)}branch.children.push({label:[v.cohort_year&&v.cohort_year+'级',v.major,v.version_name].filter(Boolean).join(' · ')||'通用版本'})}return[...roots.values()]})
const assessmentTotal=computed(()=>Number(byType('assessment_scheme')[0]?.structured?.weight_total||0))
const chineseNumbers:Row={一:1,二:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9,十:10,十一:11,十二:12,十三:13,十四:14,十五:15,十六:16,十七:17,十八:18,十九:19,二十:20}
function experimentNumber(value:any){const direct=Number(value?.structured?.experiment_number??value?.experiment_number);if(Number.isFinite(direct)&&direct>0)return direct;const text=[value?.title,value?.original_name,value?.relative_path].filter(Boolean).join(' ');const match=text.match(/实验\s*([一二三四五六七八九十百\d]+)/i);if(!match)return null;if(/^\d+$/.test(match[1]))return Number(match[1]);return chineseNumbers[match[1]]||null}
function cleanExperimentTitle(value:string){return String(value||'').normalize('NFKC').replace(/实验\s*[一二三四五六七八九十百\d]+/ig,'').replace(/[\s（）()《》【】\-_—:：、，,。]/g,'').toLowerCase()}
const experimentMatrix=computed(()=>{const groups=new Map<string,Row>();for(const project of byType('experiment_project')){const number=experimentNumber(project);const titleKey=cleanExperimentTitle(project.title);const key=`${number??'x'}:${titleKey}`;if(!groups.has(key))groups.set(key,{key,number,title:project.title,projects:[],hours:[],materials:[],reports:[],attachments:[]});const group=groups.get(key)!;group.projects.push(project);if(project.structured?.hours&&!group.hours.includes(project.structured.hours))group.hours.push(project.structured.hours)}for(const group of groups.values()){const ids=new Set(group.projects.map((x:Row)=>x.item_id));const matches=(x:Row)=>{const number=experimentNumber(x);return number!=null&&number===group.number};group.materials=byType('experiment_material').filter(matches);group.reports=byType('experiment_report').filter(matches);group.attachments=attachments.value.filter((x:Row)=>ids.has(x.experiment_item_id)||(experimentNumber(x)!=null&&experimentNumber(x)===group.number))}return[...groups.values()].sort((a,b)=>(a.number??999)-(b.number??999)||a.title.localeCompare(b.title,'zh-CN'))})
const matchedAttachmentIds=computed(()=>new Set(experimentMatrix.value.flatMap((x:Row)=>x.attachments.map((a:Row)=>a.attachment_id))))
const unmatchedExperimentFiles=computed(()=>[...byType('experiment_material').filter((x:Row)=>experimentNumber(x)==null||!experimentMatrix.value.some((g:Row)=>g.number===experimentNumber(x))),...byType('experiment_report').filter((x:Row)=>experimentNumber(x)==null||!experimentMatrix.value.some((g:Row)=>g.number===experimentNumber(x))),...attachments.value.filter((x:Row)=>!matchedAttachmentIds.value.has(x.attachment_id))])
function fail(e:any,text:string){ElMessage.error(e?.response?.data?.detail||e?.message||text)}
function tag(status:string){return status==='published'?'success':status==='review_required'?'warning':status==='failed'?'danger':'info'}
async function init(){try{const result=await Promise.all([api.get('/teacher/courses'),api.get('/teacher/terms')]);courses.value=result[0].data;terms.value=result[1].data;if(courses.value.length){courseId.value=courses.value[0].course_id;await load()}}catch(e:any){fail(e,'初始化失败')}}
async function load(){if(!courseId.value)return;loading.value=true;try{data.value=(await api.get(`/teacher/courses/${courseId.value}/teaching-archive/workbench`,{params:params()})).data}catch(e:any){fail(e,'教学档案加载失败')}finally{loading.value=false}}
async function reset(){Object.keys(filters).forEach(k=>(filters as Row)[k]='');await load()}
function openImport(){Object.assign(defaults,{term_id:terms.value[0]?.term_id||'',campus:'',cohort_year:'',major:'',class_variant:'',teaching_level:''});chosen.value=[];batch.value=null;uploadFailures.value=[];Object.assign(uploadProgress,{current:0,total:0,uploaded:0,skipped:0,failed:0,currentName:''});importStep.value=0;importOpen.value=true}
function chooseFiles(e:Event){chosen.value=Array.from((e.target as HTMLInputElement).files||[]);uploadFailures.value=[];Object.assign(uploadProgress,{current:0,total:chosen.value.length,uploaded:0,skipped:chosen.value.filter(file=>file.size===0).length,failed:0,currentName:''})}
function chooseStandaloneFiles(e:Event){openImport();chosen.value=Array.from((e.target as HTMLInputElement).files||[]);uploadProgress.total=chosen.value.length;importStep.value=1;(e.target as HTMLInputElement).value=''}
async function upload(){if(!chosen.value.length)return ElMessage.warning('请选择一个或多个文件，或选择整个教学资料文件夹');working.value=true;uploadFailures.value=[];Object.assign(uploadProgress,{current:0,total:chosen.value.length,uploaded:0,skipped:0,failed:0,currentName:''});try{const created=(await api.post(`/teacher/courses/${courseId.value}/teaching-archive/import-batches`,{term_id:defaults.term_id||null,batch_name:`教学档案导入 ${new Date().toLocaleString()}`,defaults})).data;batch.value=created;const batchId=created.batch_id;for(const [index,file] of chosen.value.entries()){uploadProgress.current=index+1;uploadProgress.currentName=(file as any).webkitRelativePath||file.name;if(file.size===0){uploadProgress.skipped++;uploadFailures.value.push({name:uploadProgress.currentName,reason:'空文件，已跳过'});continue}const form=new FormData();form.append('file',file,file.name);form.append('relative_path',uploadProgress.currentName);try{await api.post(`/teacher/teaching-archive/import-batches/${batchId}/files`,form,{timeout:0});uploadProgress.uploaded++}catch(e:any){uploadProgress.failed++;uploadFailures.value.push({name:uploadProgress.currentName,reason:e?.response?.data?.detail||'浏览器无法读取或服务器拒绝'})}}const uploadedBatch=(await api.get(`/teacher/teaching-archive/import-batches/${batchId}`)).data;batch.value=uploadedBatch;if(!uploadedBatch.files.length){failureOpen.value=uploadFailures.value.length>0;return ElMessage.error('所选内容没有可提交的非空安全文件')}importStep.value=2;duplicateOpen.value=duplicateRows.value.length>0;failureOpen.value=uploadFailures.value.length>0;if(uploadProgress.failed||uploadProgress.skipped)ElMessage.warning(`已上传 ${uploadProgress.uploaded} 个；跳过 ${uploadProgress.skipped} 个空文件，失败 ${uploadProgress.failed} 个`);else ElMessage.success(`已完整上传 ${uploadProgress.uploaded} 个文件`)}catch(e:any){fail(e,'无法创建档案导入批次')}finally{working.value=false;uploadProgress.currentName=''}}
async function commit(){if(!batch.value)return;working.value=true;try{for(const row of batch.value.files){if(['blocked','ignored'].includes(row.status))continue;await api.patch(`/teacher/teaching-archive/import-batches/${batch.value.batch_id}/files/${row.file_id}`,{record_type:row.confirmed_record_type,routing_target:row.routing_target,scope:row.scope,class_ids:row.class_ids||[],duplicate_action:row.duplicate_action||'none'})}batch.value=(await api.post(`/teacher/teaching-archive/import-batches/${batch.value.batch_id}/commit`,{},{timeout:0})).data;importStep.value=3;await load()}catch(e:any){fail(e,'提交导入失败')}finally{working.value=false}}
function openItem(row:Row){item.value={...row,structuredText:JSON.stringify(row.structured||{},null,2)};detailOpen.value=true}
async function saveItem(){if(!item.value)return;try{const structured=JSON.parse(item.value.structuredText||'{}');await api.patch(`/teacher/teaching-archive/items/${item.value.item_id}`,{title:item.value.title,content_markdown:item.value.content_markdown,structured});ElMessage.success('已保存');detailOpen.value=false;await load()}catch(e:any){fail(e,'保存失败')}}
async function setLifecycle(row:Row,state:'publish'|'withdraw'){try{await api.post(`/teacher/teaching-archive/items/${row.item_id}/${state}`);ElMessage.success(state==='publish'?'已发布':'已撤回');detailOpen.value=false;await load()}catch(e:any){fail(e,'状态更新失败')}}
function clearPreview(){if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value='';previewHtml.value='';previewError.value='';if(pptHost.value)pptHost.value.innerHTML=''}
async function preview(row:Row){clearPreview();previewDoc.value=row;previewOpen.value=true;await nextTick();try{const path=`/teacher/teaching-archive/documents/${row.archive_document_id}/preview`;if(['docx','xlsx','text','markdown'].includes(row.preview_kind))previewHtml.value=(await api.get(path,{responseType:'text'})).data;else if(row.preview_kind==='pdf'){const r=await api.get(path,{responseType:'blob'});previewUrl.value=URL.createObjectURL(r.data)}else if(row.preview_kind==='pptx'){const r=await api.get(path,{responseType:'arraybuffer'});await nextTick();if(!pptHost.value)throw new Error('PPT预览容器未准备好');const{init}=await import('pptx-preview');const width=Math.max(680,pptHost.value.clientWidth-32);await init(pptHost.value,{width,height:Math.round(width*9/16),mode:'list'}).preview(r.data)}else previewError.value='该文件暂无网页预览'}catch(e:any){previewError.value=e?.response?.data?.detail||e?.message||'预览失败'}}
async function createClass(){if(!classForm.term_id||!classForm.class_name)return ElMessage.warning('请填写学年学期和教学班名称');try{await api.post('/teacher/classes',{...classForm,course_id:courseId.value});classOpen.value=false;ElMessage.success('教学班已创建');await load()}catch(e:any){fail(e,'创建失败')}}
async function compare(){if(!compareLeft.value||!compareRight.value||compareLeft.value===compareRight.value)return ElMessage.warning('请选择两个不同版本');try{comparison.value=(await api.get('/teacher/teaching-archive/versions/compare',{params:{left_version_id:compareLeft.value,right_version_id:compareRight.value}})).data}catch(e:any){fail(e,'比较失败')}}
async function deleteDocument(row:Row){try{await ElMessageBox.confirm(`确定删除“${row.original_name}”及其结构化档案项吗？此操作不可撤销。`,'删除冗余档案',{type:'warning',confirmButtonText:'确认删除'});await api.delete(`/teacher/teaching-archive/documents/${row.archive_document_id}`);ElMessage.success('冗余档案已删除');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')fail(e,'删除失败')}}
async function deleteAttachment(row:Row){try{await ElMessageBox.confirm(`确定删除附件“${row.original_name}”吗？此操作不可撤销。`,'删除冗余附件',{type:'warning',confirmButtonText:'确认删除'});await api.delete(`/teacher/teaching-archive/attachments/${row.attachment_id}`);ElMessage.success('冗余附件已删除');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')fail(e,'删除失败')}}
onMounted(init);onBeforeUnmount(clearPreview)
</script>

<template>
<main class="content archive" v-loading="loading">
  <header class="hero"><div><span>TEACHING IMPLEMENTATION ARCHIVE</span><h1>教学档案工作台</h1><p>把大纲、教案、进度、考核与实验材料组织成可筛选、可比较、可追溯的教学实施版本。</p></div><div><el-button @click="classOpen=true">新增教学班</el-button><label class="hero-file-button"><input type="file" multiple accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt,.md,.zip,.rar,.7z,.bak" @change="chooseStandaloneFiles"/>选择单个/多个文件</label><el-button type="primary" @click="openImport">整包导入档案</el-button></div></header>
  <section class="filters"><el-select v-model="courseId" @change="reset"><el-option v-for="x in courses" :key="x.course_id" :label="x.course_name" :value="x.course_id"/></el-select><el-select v-model="filters.term_id" clearable placeholder="学年学期" @change="load"><el-option v-for="x in terms" :key="x.term_id" :label="`${x.academic_year||''} ${x.teaching_period||x.term_name}`" :value="x.term_id"/></el-select><el-select v-model="filters.campus" clearable placeholder="校区" @change="load"><el-option v-for="x in options('campus')" :key="x" :label="x" :value="x"/></el-select><el-select v-model="filters.cohort_year" clearable placeholder="入学年级" @change="load"><el-option v-for="x in options('cohort_year')" :key="x" :label="x+'级'" :value="x"/></el-select><el-select v-model="filters.major" clearable placeholder="专业" @change="load"><el-option v-for="x in options('major')" :key="x" :label="x" :value="x"/></el-select><el-select v-model="filters.class_id" clearable placeholder="教学班" @change="load"><el-option v-for="x in classes" :key="x.class_id" :label="x.class_name" :value="x.class_id"/></el-select><el-button text @click="reset">清空</el-button></section>
  <section class="metrics"><article><span>档案完整度</span><strong>{{metrics.completeness}}%</strong><el-progress :percentage="metrics.completeness" :show-text="false"/></article><article><span>已发布文件</span><strong>{{metrics.published_documents}}</strong><small>正式教学档案</small></article><article :class="{warn:metrics.review_required}"><span>待审核异常</span><strong>{{metrics.review_required}}</strong><small>降级和冲突不会自动发布</small></article><article><span>教学班覆盖</span><strong>{{metrics.class_coverage}}%</strong><small>{{metrics.hours_consistent?'课时校验正常':'存在课时差异'}}</small></article></section>
  <section class="work"><aside><div class="pane-title"><b>档案目录</b><small>{{versions.length}} 个版本</small></div><el-tree :data="tree" default-expand-all/><div class="hint">按学年学期、校区、年级/专业、教学班与自定义版本组织</div></aside>
    <section class="main"><el-tabs v-model="tab">
      <el-tab-pane label="总览" name="overview"><div class="overview"><article class="panel"><h2>本学期教学时间轴</h2><div class="timeline"><div v-for="x in byType('teaching_schedule_entry').slice(0,10)" :key="x.item_id" @click="openItem(x)"><i/><p><b>{{x.title}}</b><span>{{x.structured.sheet}} · 第{{x.structured['周次']||'—'}}周 · {{x.structured['节次']||''}}</span></p><el-tag size="small">{{x.structured['授课性质']||'教学'}}</el-tag></div></div><el-empty v-if="!byType('teaching_schedule_entry').length" description="导入教学进度表后生成时间轴"/></article><article class="panel"><h2>教学班覆盖矩阵</h2><div v-for="x in classes" :key="x.class_id" class="coverage"><p><b>{{x.class_name}}</b><span>{{[x.campus,x.cohort_year&&x.cohort_year+'级',x.major,x.class_variant].filter(Boolean).join(' · ')}}</span></p><div><i v-for="t in ['syllabus_profile','lesson_session','teaching_schedule_entry','assessment_scheme','experiment_project']" :key="t" :class="{on:byType(t).length}" :title="labels[t]"/></div></div><el-empty v-if="!classes.length" description="请先创建教学班"/></article></div><article class="panel docs"><h2>档案文件</h2><el-table :data="documents"><el-table-column prop="original_name" label="文件" min-width="250"/><el-table-column label="类型" width="120"><template #default="s">{{docLabels[s.row.record_type]||s.row.record_type}}</template></el-table-column><el-table-column label="状态" width="120"><template #default="s"><el-tag :type="tag(s.row.lifecycle)">{{s.row.lifecycle}}</el-tag></template></el-table-column><el-table-column label="操作" width="90"><template #default="s"><el-button link type="primary" @click="preview(s.row)">预览</el-button></template></el-table-column></el-table></article></el-tab-pane>
      <el-tab-pane label="档案目录" name="directory"><div class="list"><article v-for="x in items" :key="x.item_id" @click="openItem(x)"><div><el-tag size="small" effect="plain">{{labels[x.record_type]}}</el-tag><h3>{{x.title}}</h3><p>{{x.content_markdown?.slice(0,180)||'暂无正文摘要'}}</p><small>{{x.original_name}}</small></div><el-tag :type="tag(x.lifecycle)">{{x.lifecycle}}</el-tag></article><el-empty v-if="!items.length" description="尚无结构化档案"/></div></el-tab-pane>
      <el-tab-pane label="教学周历" name="schedule"><div class="cards"><article v-for="x in byType('teaching_schedule_entry')" :key="x.item_id" @click="openItem(x)"><span>第 {{x.structured['周次']||'—'}} 周</span><h3>{{x.title}}</h3><p>{{x.structured['日期']||''}} · {{x.structured['节次']||''}}</p><small>{{x.structured.sheet}} / {{x.structured['授课班级']||''}}</small></article></div><el-empty v-if="!byType('teaching_schedule_entry').length" description="尚未导入教学进度表"/></el-tab-pane>
      <el-tab-pane label="教案课次" name="lessons"><div class="cards"><article v-for="x in byType('lesson_session')" :key="x.item_id" @click="openItem(x)"><span>LESSON {{x.structured.session_number||'—'}}</span><h3>{{x.structured.chapter||x.title}}</h3><p>{{x.structured.duration||'未识别课时'}}</p><el-tag size="small" :type="tag(x.lifecycle)">{{x.lifecycle}}</el-tag></article></div><el-empty v-if="!byType('lesson_session').length" description="尚未导入教案"/></el-tab-pane>
      <el-tab-pane label="实验矩阵" name="experiments">
        <div class="experiment-help"><article><b>教学材料</b><span>实验前/实验中使用的指导书、讲义、源码、数据库与压缩附件。</span></article><article><b>实验报告</b><span>报告模板或完成后的实验记录，与教学材料分开归档。</span></article><article><b>匹配规则</b><span>按“实验编号＋名称”归并；来自多个大纲的同一项目只显示一行。</span></article></div>
        <el-table :data="experimentMatrix" class="experiment-table">
          <el-table-column type="expand"><template #default="s"><div class="experiment-detail"><section><b>材料明细</b><p v-for="x in [...s.row.materials,...s.row.attachments]" :key="x.item_id||x.attachment_id">{{x.original_name||x.title}} <el-tag size="small" effect="plain">{{x.attachment_type||'结构化材料'}}</el-tag></p><small v-if="!s.row.materials.length&&!s.row.attachments.length">尚未匹配材料</small></section><section><b>报告明细</b><p v-for="x in s.row.reports" :key="x.item_id">{{x.original_name||x.title}}</p><small v-if="!s.row.reports.length">尚未匹配报告</small></section><section><b>大纲来源</b><p v-for="x in s.row.projects" :key="x.item_id">{{x.original_name}}</p></section></div></template></el-table-column>
          <el-table-column prop="number" label="序号" width="70"/>
          <el-table-column prop="title" label="实验项目" min-width="320"><template #default="s"><b>{{s.row.title}}</b><el-tag v-if="s.row.projects.length>1" size="small" type="warning" effect="plain">{{s.row.projects.length}} 个版本来源</el-tag></template></el-table-column>
          <el-table-column label="学时" width="110"><template #default="s"><span :class="{conflict:s.row.hours.length>1}">{{s.row.hours.join(' / ')||'—'}}</span></template></el-table-column>
          <el-table-column label="教学材料" width="130"><template #default="s"><el-tag :type="s.row.materials.length+s.row.attachments.length?'success':'info'">{{s.row.materials.length+s.row.attachments.length?`${s.row.materials.length+s.row.attachments.length} 项`:'待匹配'}}</el-tag></template></el-table-column>
          <el-table-column label="实验报告" width="130"><template #default="s"><el-tag :type="s.row.reports.length?'success':'info'">{{s.row.reports.length?`${s.row.reports.length} 项`:'待补充'}}</el-tag></template></el-table-column>
        </el-table>
        <el-alert v-if="unmatchedExperimentFiles.length" class="unmatched" type="warning" :closable="false" :title="`${unmatchedExperimentFiles.length} 个材料或报告无法确定对应实验，已保留在待匹配区，没有强行挂接。`"/>
      </el-tab-pane>
      <el-tab-pane label="考核方案" name="assessment"><div class="assessment"><div class="donut" :style="{'--v':Math.min(assessmentTotal,100)+'%'}"><strong>{{assessmentTotal}}%</strong><span>总权重</span></div><div><h2>课程考核组成</h2><el-alert v-if="assessmentTotal!==100&&byType('assessment_scheme').length" type="warning" :closable="false" title="考核权重不等于100%，已阻止自动发布"/><article v-for="x in byType('assessment_scheme')" :key="x.item_id" @click="openItem(x)"><p v-for="c in x.structured.components||[]" :key="c.name"><span>{{c.name}}</span><b>{{c.weight}}%</b></p><pre>{{x.content_markdown}}</pre></article></div></div></el-tab-pane>
      <el-tab-pane :label="`待审核 ${reviewItems.length}`" name="review"><div class="review"><article v-for="x in reviewItems" :key="x.item_id"><div><h3>{{x.title}}</h3><p>{{x.risk_codes.map((r:string)=>riskLabels[r]||r).join('、')}}</p></div><div><el-button @click="openItem(x)">检查</el-button><el-button type="success" @click="setLifecycle(x,'publish')">确认发布</el-button></div></article><el-empty v-if="!reviewItems.length" description="没有待审核异常"/></div></el-tab-pane>
      <el-tab-pane label="版本比较" name="compare"><div class="compare"><el-select v-model="compareLeft" placeholder="基准版本"><el-option v-for="x in versions" :key="x.version_id" :label="x.version_name" :value="x.version_id"/></el-select><span>对比</span><el-select v-model="compareRight" placeholder="目标版本"><el-option v-for="x in versions" :key="x.version_id" :label="x.version_name" :value="x.version_id"/></el-select><el-button type="primary" @click="compare">生成差异</el-button></div><el-table v-if="comparison" :data="comparison.differences"><el-table-column prop="key" label="档案项"/><el-table-column prop="state" label="变化" width="120"/><el-table-column label="基准"><template #default="s">{{s.row.left?.title||'—'}}</template></el-table-column><el-table-column label="目标"><template #default="s">{{s.row.right?.title||'—'}}</template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane :label="`文件管理 ${documents.length+attachments.length}`" name="files">
        <section class="file-management"><el-alert type="info" :closable="false" title="删除会同时移除该文件生成的结构化档案项；请先确认它确属重复或冗余文件。"/>
          <h3>可预览教学文件</h3><el-table :data="documents"><el-table-column prop="relative_path" label="来源目录" min-width="240"/><el-table-column prop="original_name" label="文件" min-width="220"/><el-table-column label="状态" width="120"><template #default="s"><el-tag :type="tag(s.row.lifecycle)">{{s.row.lifecycle}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="preview(s.row)">预览</el-button><el-button link type="danger" @click="deleteDocument(s.row)">删除</el-button></template></el-table-column></el-table>
          <h3>实验与压缩附件</h3><el-table :data="attachments"><el-table-column prop="original_name" label="附件" min-width="260"/><el-table-column prop="attachment_type" label="类型"/><el-table-column label="操作" width="90"><template #default="s"><el-button link type="danger" @click="deleteAttachment(s.row)">删除</el-button></template></el-table-column></el-table>
        </section>
      </el-tab-pane>
    </el-tabs></section>
  </section>

  <el-dialog v-model="importOpen" title="整包导入教学档案" width="min(1180px,96vw)" :close-on-click-modal="false"><el-steps :active="importStep" finish-status="success"><el-step title="确定范围"/><el-step title="选择文件"/><el-step title="确认分类"/><el-step title="完成"/></el-steps><section v-if="importStep<2" class="import"><div class="import-grid"><el-select v-model="defaults.term_id" placeholder="学年学期"><el-option v-for="x in terms" :key="x.term_id" :label="`${x.academic_year||''} ${x.teaching_period||x.term_name}`" :value="x.term_id"/></el-select><el-input v-model="defaults.campus" placeholder="校区：本部 / 仁济"/><el-input v-model="defaults.cohort_year" placeholder="入学年级：2024"/><el-input v-model="defaults.major" placeholder="专业"/><el-input v-model="defaults.class_variant" placeholder="自定义版本：A班"/><el-input v-model="defaults.teaching_level" placeholder="教学层级/难度（可选）"/></div><label class="drop"><input type="file" multiple webkitdirectory @change="chooseFiles"/><b>选择整个教学资料文件夹</b><span>保留目录并自动识别类型、校区、年级和专业</span><em>{{chosen.length?`已选择 ${chosen.length} 个文件`:'尚未选择'}}</em></label><el-alert type="info" :closable="false" title="EXE/DLL、IDE缓存、bin/obj 会被拦截或忽略；ZIP/RAR 只作安全附件。"/></section><section v-else-if="importStep===2" class="classify"><el-table :data="batch?.files||[]" height="500"><el-table-column prop="relative_path" label="文件" min-width="260"/><el-table-column label="类型" width="160"><template #default="s"><el-select v-model="s.row.confirmed_record_type" :disabled="['blocked','ignored'].includes(s.row.status)"><el-option v-for="(v,k) in docLabels" :key="k" :label="v" :value="k"/></el-select></template></el-table-column><el-table-column label="去向" width="140"><template #default="s"><el-select v-model="s.row.routing_target" :disabled="['blocked','ignored'].includes(s.row.status)"><el-option v-for="(v,k) in routeLabels" :key="k" :label="v" :value="k"/></el-select></template></el-table-column><el-table-column label="教学班" min-width="220"><template #default="s"><el-select v-model="s.row.class_ids" multiple collapse-tags :disabled="['blocked','ignored'].includes(s.row.status)"><el-option v-for="x in classes" :key="x.class_id" :label="x.class_name" :value="x.class_id"/></el-select></template></el-table-column><el-table-column label="状态" width="110"><template #default="s"><el-tag :type="s.row.status==='blocked'?'danger':'info'">{{s.row.status}}</el-tag></template></el-table-column></el-table></section><section v-else class="done"><i>✓</i><h2>导入完成</h2><p>正常内容已发布，异常内容已进入待审核队列。</p><div><b>已发布 {{batch?.published_count||0}}</b><b>待审核 {{batch?.review_count||0}}</b><b>失败/拦截 {{batch?.error_count||0}}</b></div></section><template #footer><el-button @click="importOpen=false">{{importStep===3?'关闭':'取消'}}</el-button><el-button v-if="importStep<2" type="primary" :loading="working" @click="upload">上传并预分类</el-button><el-button v-else-if="importStep===2" type="primary" :loading="working" @click="commit">确认并建立档案</el-button></template></el-dialog>

  <div v-if="working&&uploadProgress.total" class="upload-live"><b>整包上传 {{uploadProgress.current}} / {{uploadProgress.total}}</b><el-progress :percentage="Math.round(uploadProgress.current*100/uploadProgress.total)"/><span>{{uploadProgress.currentName}}</span><small>成功 {{uploadProgress.uploaded}} · 空文件跳过 {{uploadProgress.skipped}} · 失败 {{uploadProgress.failed}}</small></div>
  <el-dialog v-model="duplicateOpen" title="确认重复文件的版本处理" width="min(760px,94vw)" append-to-body><el-alert type="warning" :closable="false" title="内容哈希相同的文件默认跳过，不会重复入库。只有确需保留为新教学版本时才选择“作为新版本导入”。"/><div v-for="row in duplicateRows" :key="row.file_id" class="duplicate-row"><div><b>{{row.original_name}}</b><small>{{row.error_message}}</small></div><el-select v-model="row.duplicate_action"><el-option label="跳过重复文件（推荐）" value="skip"/><el-option label="作为新版本导入" value="new_version"/></el-select></div><template #footer><el-button type="primary" @click="duplicateOpen=false">确认处理方式</el-button></template></el-dialog>
  <el-dialog v-model="failureOpen" title="整包导入中已跳过的文件" width="min(800px,94vw)" append-to-body><el-alert type="info" :closable="false" title="单个空文件或读取失败不会再中断整个文件夹，其余文件已继续上传。"/><el-table :data="uploadFailures" max-height="420"><el-table-column prop="name" label="文件" min-width="300"/><el-table-column prop="reason" label="原因" min-width="220"/></el-table><template #footer><el-button type="primary" @click="failureOpen=false">知道了</el-button></template></el-dialog>
  <el-drawer v-model="detailOpen" title="档案项详情" size="min(720px,94vw)"><template v-if="item"><div class="status"><el-tag>{{labels[item.record_type]}}</el-tag><el-tag :type="tag(item.lifecycle)">{{item.lifecycle}}</el-tag></div><el-form label-position="top"><el-form-item label="标题"><el-input v-model="item.title"/></el-form-item><el-form-item label="结构化字段"><el-input v-model="item.structuredText" type="textarea" :rows="11"/></el-form-item><el-form-item label="正文"><el-input v-model="item.content_markdown" type="textarea" :rows="13"/></el-form-item></el-form><div v-if="item.risk_codes?.length" class="risks"><b>发布风险</b><p v-for="r in item.risk_codes" :key="r">{{riskLabels[r]||r}}</p></div><div class="actions"><el-button type="primary" @click="saveItem">保存</el-button><el-button v-if="item.lifecycle!=='published'" type="success" @click="setLifecycle(item,'publish')">确认发布</el-button><el-button v-else type="warning" @click="setLifecycle(item,'withdraw')">撤回</el-button></div></template></el-drawer>
  <el-drawer v-model="previewOpen" title="原文件预览" size="min(1040px,96vw)" @closed="clearPreview"><template v-if="previewDoc"><div class="preview-head"><b>{{previewDoc.original_name}}</b></div><iframe v-if="previewHtml" sandbox="" :srcdoc="previewHtml"/><iframe v-else-if="previewUrl" :src="previewUrl"/><div v-else-if="previewDoc.preview_kind==='pptx'" ref="pptHost" class="ppt"/><el-result v-else icon="warning" title="预览不可用" :sub-title="previewError"/></template></el-drawer>
  <el-dialog v-model="classOpen" title="新增教学班与教学版本" width="min(680px,94vw)"><el-form label-position="top"><div class="class-grid"><el-form-item label="学年学期"><el-select v-model="classForm.term_id"><el-option v-for="x in terms" :key="x.term_id" :label="`${x.academic_year||''} ${x.teaching_period||x.term_name}`" :value="x.term_id"/></el-select></el-form-item><el-form-item label="教学班名称"><el-input v-model="classForm.class_name" placeholder="仁24信管1"/></el-form-item><el-form-item label="校区"><el-input v-model="classForm.campus" placeholder="本部 / 仁济"/></el-form-item><el-form-item label="入学年级"><el-input v-model="classForm.cohort_year" placeholder="2024"/></el-form-item><el-form-item label="专业"><el-input v-model="classForm.major"/></el-form-item><el-form-item label="自定义版本"><el-input v-model="classForm.class_variant" placeholder="A班 / 强化版"/></el-form-item><el-form-item label="教学层级/难度"><el-input v-model="classForm.teaching_level"/></el-form-item><el-form-item label="授课时间"><el-input v-model="classForm.teaching_time_slot"/></el-form-item></div></el-form><template #footer><el-button @click="classOpen=false">取消</el-button><el-button type="primary" @click="createClass">创建</el-button></template></el-dialog>
</main>
</template>

